<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class ProductTranslationsSchema extends SchemaDefinition { protected string $table = 'product_translations'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('product_id'); $table->string_50('locale')->index(); $table->string_255('name'); $table->string_255('short_description')->nullable(); $table->long_text('description')->nullable(); $table->foreign('product_id')->references('id')->on('products')->onDelete('CASCADE'); $table->unique('product_id', 'locale'); } } 